import{_ as o,c as a,o as r,ag as s}from"./chunks/framework.B-XtCDNB.js";const i="/assets/1.0/images/configurable-product/configurable.png",n="/assets/1.0/images/configurable-product/configurableAttributes.png",c="/assets/1.0/images/configurable-product/editProduct.png",p="/assets/1.0/images/configurable-product/description.png",l="/assets/1.0/images/configurable-product/status.png",d="/assets/1.0/images/configurable-product/category.png",u="/assets/1.0/images/configurable-product/variant.png",g="/assets/1.0/images/configurable-product/addVariant.png",t="/assets/1.0/images/configurable-product/upsell.png",h="/assets/1.0/images/configurable-product/save.png",m="/assets/1.0/images/configurable-product/datagrid.png",b="/assets/1.0/images/configurable-product/history.png",f="/assets/1.0/images/configurable-product/preview.png",_="/assets/1.0/images/configurable-product/export.png",w="/assets/1.0/images/configurable-product/exportOutput.png",P="/assets/1.0/images/configurable-product/final.png",U=JSON.parse('{"title":"Configurable Product","description":"","frontmatter":{},"headers":[],"relativePath":"1.0/products/configurable.md","filePath":"1.0/products/configurable.md","lastUpdated":1759498853000}'),y={name:"1.0/products/configurable.md"};function v(S,e,k,C,q,x){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="configurable-product" tabindex="-1">Configurable Product <a class="header-anchor" href="#configurable-product" aria-label="Permalink to &quot;Configurable Product&quot;">​</a></h1><p>It refers to a type of product that offers various options or variations, such as size, color, or features, which can be selected by the customer. The PIM system manages these options and their associated attributes, ensuring accurate and comprehensive product information across different configurations.</p><p>Configurable products are designed to meet individual needs, enhancing customer satisfaction and providing a tailored experience in <a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a>.</p><h3 id="create-configurable-product-in-unopim" tabindex="-1">Create Configurable Product in UnoPim <a class="header-anchor" href="#create-configurable-product-in-unopim" aria-label="Permalink to &quot;Create Configurable Product in UnoPim&quot;">​</a></h3><ol><li>Click on <strong>Catalog &gt;&gt; Products &gt;&gt;</strong> select <strong>Configurable</strong> , <strong>Family</strong> and enter <strong>SKU</strong> under Product Type .</li></ol><p><img src="'+i+'" alt="Configurable"></p><p>Now click on <strong>Save the Product</strong>, and now select the <strong>configurable attributes</strong> as per your requirements, and then click on <strong>Save Product</strong> button as shown in the image below.</p><p><img src="'+n+'" alt="ConfigurableAttributes"></p><h3 id="general-attributes" tabindex="-1">General Attributes <a class="header-anchor" href="#general-attributes" aria-label="Permalink to &quot;General Attributes&quot;">​</a></h3><p>It displays the attributes assigned in the product&#39;s family grouped by attribute group.</p><p>The below given are required attributes present in the &quot;default&quot; family</p><ol><li><p>Enter <strong>SKU</strong> of the product</p></li><li><p>Enter <strong>Name</strong> of the product</p></li><li><p>Now enter the <strong>URL Key</strong> of the product</p></li></ol><p><img src="'+c+'" alt="editProduct"></p><h3 id="short-description" tabindex="-1">Short Description <a class="header-anchor" href="#short-description" aria-label="Permalink to &quot;Short Description&quot;">​</a></h3><p>Enter a short description of the features of the product.</p><h3 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h3><p>Mention your product in detail.</p><p><img src="'+p+'" alt="description"></p><h3 id="technical" tabindex="-1">Technical <a class="header-anchor" href="#technical" aria-label="Permalink to &quot;Technical&quot;">​</a></h3><p>Now Enable the product from the status option as shown below.</p><p><img src="'+l+'" alt="Status"></p><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3><p>You can also assign the product into the root category as shown in the below image.</p><p><img src="'+d+'" alt="Category"></p><h3 id="variations" tabindex="-1">Variations <a class="header-anchor" href="#variations" aria-label="Permalink to &quot;Variations&quot;">​</a></h3><p>Now enter the variations of the product for this click on Add Product as shown in the below image.</p><p><img src="'+u+'" alt="Variant"></p><p>Now add the variant enter the configurable attributes and then click on <strong>Add button</strong> as shown in the image below.</p><p><img src="'+g+'" alt="Add Variant"></p><p>You can add as many variants as per the requirements of the product.</p><h3 id="associations" tabindex="-1">Associations <a class="header-anchor" href="#associations" aria-label="Permalink to &quot;Associations&quot;">​</a></h3><p>Also, you can add the Related Products, Upsell Products, and Cross-Sell Products.</p><p><strong>1) Related Products -</strong> Related products are products that are similar to a selected product. You can display potential substitutes help to them discover other similar products they might like.</p><p>To add Related Products click on Add in the Related Products section and search the product through the SKU which you want to add as a Related Product as shown in the image below.</p><p><img src="'+t+'" alt="Related"></p><p>Now click on <strong>Add Selected Product</strong> button.</p><p><strong>2) Up-Sell Products -</strong> Upselling is the practice of selling a higher-end version of an item they&#39;re interested in.</p><p>For instance, an electronics retailer pointing out the benefits of a better TV, a faster laptop, or a more durable tablet would be an example of upselling.</p><p>To add Up-Sell Products click on add in the Up-Sell Products section and search the product through the SKU which you want to add as a Up-Sell Product as shown in the image below.</p><p><img src="'+t+'" alt="Upsell"></p><p>Now click on <strong>Add Selected Product</strong> button.</p><p><strong>2) Cross-Sell Products -</strong> Cross-sells are products that you promote, based on the current product. They are typically complementary items. For example, if you are selling a laptop, cross-sells might be protective case stickers or a special adapter.</p><p>To add Cross-Sell Products click on add in the Cross-Sell Products section and search the product through SKU which you want to add as a Cross-Sell Product as shown in the image below.</p><p><img src="'+t+'" alt="Upsell"></p><p>Now click on <strong>Add Selected Product</strong> button.</p><p>You can also add as many products as per your requirements.</p><p>At last, <strong>Save the Product</strong>.</p><p><img src="'+h+'" alt="Save"></p><p>Now the product has been created successfully and will be visible in the Products Data Grid as shown in the image below.</p><p><img src="'+m+'" alt="Datagrid"></p><p>Additionally, you can also view the product history by navigating to <strong>Catalog &gt;&gt; Products &gt;&gt; Edit Product</strong> and clicking on <strong>History</strong> as shown below.</p><p><img src="'+b+'" alt="History"></p><p>Afterwards, in the <strong>Actions</strong> you can view the product history as shown below.</p><p><img src="'+f+'" alt="Preview"></p><p>Also, you can able to <strong>Quick Export</strong> your data into <strong>CSV, XLS, XLSX</strong> format.</p><p><img src="'+_+'" alt="Export"></p><p>Now, click on <strong>Quick Export button</strong> to export the data.</p><p><img src="'+w+'" alt="Export Output"></p><p><strong>Note-</strong> Attributes that support values per channel will display a channel badge, while attributes that support values per locale will display a locale badge. If an attribute supports both values per channel and values per locale, it will display both badges.</p><p><img src="'+P+'" alt="Export Output"></p>',60)])])}const T=o(y,[["render",v]]);export{U as __pageData,T as default};
